'use client'

import * as React from 'react'
import { Badge } from '@/components/spaceui/badge-squircle'
import { cn } from '@/lib/utils'

export interface SectionHeaderProps {
  title?: string
  description?: string
  link?: string
  badge?: string
  layoutStart?: boolean
  isPage?: boolean
}

export function SectionHeader({ title, description, link, badge, layoutStart, isPage }: SectionHeaderProps) {
  return (
    <div
      className={cn(
        'max-w-2xl flex flex-col items-start justify-start gap-4 mb-12',
        !layoutStart && 'mx-auto items-center justify-center text-center',
      )}
    >
      {badge && (
        <Badge
          size="md"
          className="squircle-2xl/80 md:squircle-3xl/80 px-3 py-1.5 border-none bg-muted text-foreground font-semibold text-base"
        >
          {badge}
        </Badge>
      )}

      {title && (
        <h2
          className={cn(
            layoutStart ? 'text-2xl md:text-3xl font-normal' : 'capitalize text-3xl md:text-4xl font-bold',
            isPage && 'font-normal',
          )}
        >
          {title}
        </h2>
      )}

      {description && (
        <p
          className={cn('text-xl md:text-2xl text-muted-foreground whitespace-pre-line', !layoutStart && 'font-medium')}
        >
          {description}
        </p>
      )}

      {link && (
        <a
          href={link}
          className="inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground transition-colors"
        >
          See more &rarr;
        </a>
      )}
    </div>
  )
}

export interface SectionLayoutProps {
  id?: string
  title?: string
  description?: string
  className?: string
  contentClassName?: string
  link?: string
  badge?: string
  children: React.ReactNode
  isFlex?: boolean
  layoutStart?: boolean
  isPage?: boolean
}

export function SectionLayout({
  id,
  title,
  description,
  className,
  contentClassName,
  link,
  badge,
  children,
  isFlex,
  layoutStart,
  isPage,
}: SectionLayoutProps) {
  return (
    <section className={cn('relative w-full py-14 md:py-[104px]', className)} id={id}>
      {(title || badge) && (
        <SectionHeader
          title={title}
          description={description}
          link={link}
          badge={badge}
          layoutStart={layoutStart}
          isPage={isPage}
        />
      )}
      <div
        className={cn(
          'flex flex-col items-center justify-center justify-items-center self-center place-self-center w-full gap-6',
          !isFlex && 'md:grid grid-cols-1 md:grid-cols-2 md:max-w-[90%] place-items-center place-self-center',
          contentClassName,
        )}
      >
        {children}
      </div>
    </section>
  )
}

'use client'

import { motion } from 'motion/react'
import * as React from 'react'
import { IconCodeCircleFilled, IconStarFilled, IconBrandGithubFilled } from '@tabler/icons-react'
import { Frame } from '@/components/ui/frame'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/spaceui/badge-squircle'
import { cn } from '@/lib/utils'
import { MOCK_GITHUB_STATS } from './mock-data'

export type GitHubStatType = 'stars' | 'forks' | 'commits'

export interface GitHubStatsCardProps {
  type: GitHubStatType
  label: string
  value: number | string
  period?: string
  className?: string
}

const starDecorations = [
  { x: '12%', y: '18%', size: 16, rotate: 0, delay: 0 },
  { x: '78%', y: '12%', size: 12, rotate: 15, delay: 0.1 },
  { x: '85%', y: '55%', size: 14, rotate: -10, delay: 0.15 },
  { x: '20%', y: '65%', size: 10, rotate: 20, delay: 0.2 },
  { x: '65%', y: '70%', size: 8, rotate: -5, delay: 0.25 },
]

const forkDecorations = [
  { x: '15%', y: '20%', rotate: -20, delay: 0 },
  { x: '80%', y: '15%', rotate: 25, delay: 0.1 },
  { x: '75%', y: '60%', rotate: -15, delay: 0.15 },
  { x: '25%', y: '70%', rotate: 10, delay: 0.2 },
]

const commitDecorations = [
  { x: '15%', y: '25%', delay: 0 },
  { x: '30%', y: '18%', delay: 0.05 },
  { x: '75%', y: '20%', delay: 0.1 },
  { x: '85%', y: '50%', delay: 0.15 },
  { x: '20%', y: '65%', delay: 0.2 },
  { x: '70%', y: '70%', delay: 0.25 },
]

function StarShape({ size, className }: { size: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
    </svg>
  )
}

function BranchShape({ className }: { className?: string }) {
  return (
    <svg
      width="20"
      height="24"
      viewBox="0 0 20 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      className={className}
    >
      <circle cx="10" cy="4" r="2" />
      <circle cx="4" cy="20" r="2" />
      <circle cx="16" cy="20" r="2" />
      <path d="M10 6v6M10 12c0 4-6 4-6 8M10 12c0 4 6 4 6 8" />
    </svg>
  )
}

function CommitDot({ className }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor" className={className}>
      <circle cx="8" cy="8" r="4" />
      <circle cx="8" cy="8" r="7" fill="none" stroke="currentColor" strokeWidth="1.5" opacity="0.3" />
    </svg>
  )
}

function GithubSvg({ size = 24, className }: { size?: number | string; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.53 1.032 1.53 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z"
      />
    </svg>
  )
}

const themeConfig = {
  stars: {
    icon: IconStarFilled,
    decorColor: 'text-amber-400',
    iconColor: 'text-amber-500',
    badgeBg: 'bg-[#ffd3ad] text-stone-900',
  },
  forks: {
    icon: IconCodeCircleFilled,
    decorColor: 'text-amber-400',
    iconColor: 'text-amber-500',
    badgeBg: 'bg-[#ffd3ad] text-stone-900',
  },
  commits: {
    icon: GithubSvg,
    decorColor: 'text-amber-400',
    iconColor: 'text-amber-500',
    badgeBg: 'bg-[#ffd3ad] text-stone-900',
  },
}

export function GitHubStatsCard({ type, label, value, period, className }: GitHubStatsCardProps) {
  const [isHovered, setIsHovered] = React.useState(false)

  const theme = themeConfig[type]
  const Icon = theme.icon

  return (
    <Frame
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={cn('flex-1 size-full bg-muted squircle-3xl/60 border-0 overflow-hidden p-2', className)}
    >
      <Card className="relative squircle-4xl/100 bg-background border-0 overflow-hidden size-full p-0 flex flex-row items-center before:hidden shadow-none">
        <div className="pointer-events-none absolute inset-0 overflow-hidden select-none">
          {type === 'stars' &&
            starDecorations.map((star, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, scale: 0, rotate: star.rotate - 30 }}
                animate={{
                  opacity: isHovered ? 0.55 : 0.3,
                  scale: isHovered ? 1.4 : 1,
                  rotate: isHovered ? star.rotate + 15 : star.rotate,
                  y: isHovered ? -8 : 0,
                }}
                transition={{
                  opacity: { duration: 0.2 },
                  scale: { type: 'spring', stiffness: 200, damping: 15 },
                  rotate: { type: 'spring', stiffness: 200, damping: 15 },
                  y: { type: 'spring', stiffness: 200, damping: 15 },
                }}
                className={`absolute ${theme.decorColor}`}
                style={{ left: star.x, top: star.y }}
              >
                <StarShape size={star.size} />
              </motion.div>
            ))}

          {type === 'forks' &&
            forkDecorations.map((fork, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, scale: 0, rotate: fork.rotate }}
                animate={{
                  opacity: isHovered ? 0.5 : 0.28,
                  scale: isHovered ? 1.3 : 1,
                  rotate: isHovered ? fork.rotate * 1.3 : fork.rotate,
                  y: isHovered ? -8 : 0,
                }}
                transition={{
                  opacity: { duration: 0.2 },
                  scale: { type: 'spring', stiffness: 200, damping: 15 },
                  rotate: { type: 'spring', stiffness: 200, damping: 15 },
                  y: { type: 'spring', stiffness: 200, damping: 15 },
                }}
                className={`absolute ${theme.decorColor}`}
                style={{ left: fork.x, top: fork.y }}
              >
                <BranchShape />
              </motion.div>
            ))}

          {type === 'commits' &&
            commitDecorations.map((commit, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, scale: 0 }}
                animate={{
                  opacity: isHovered ? 0.55 : 0.32,
                  scale: isHovered ? 1.5 : 1,
                  y: isHovered ? -6 : 0,
                }}
                transition={{
                  opacity: { duration: 0.2 },
                  scale: { type: 'spring', stiffness: 250, damping: 15 },
                  y: { type: 'spring', stiffness: 200, damping: 15 },
                }}
                className={`absolute ${theme.decorColor}`}
                style={{ left: commit.x, top: commit.y }}
              >
                <CommitDot />
              </motion.div>
            ))}
        </div>

        <div className="relative size-full flex flex-row z-20 overflow-hidden items-center gap-2 md:gap-4 px-2 py-2 m-auto">
          <Badge
            className={cn('capitalize whitespace-pre-line size-auto squircle-2xl/80 md:squircle-3xl/80', theme.badgeBg)}
            variant="default"
            size="lg"
          >
            <Icon size={32} />
          </Badge>
          <div className="flex flex-col items-start gap-2">
            <h6 className="tracking-wide text-foreground whitespace-pre-line font-medium text-sm md:text-base leading-tight">
              {label}
            </h6>
            <p className="text-sm text-muted-foreground leading-[120%] font-medium">{value}</p>
            {period && <p className="mt-1 text-xs text-muted-foreground">{period}</p>}
          </div>
        </div>
      </Card>
    </Frame>
  )
}

export interface GitHubStatsProps {
  stars?: number
  forks?: number
  commits?: number
  shape?: 'square' | 'rounded' | 'circle'
  className?: string
}

export function GitHubStats({
  stars = MOCK_GITHUB_STATS.stars,
  forks = MOCK_GITHUB_STATS.forks,
  commits = MOCK_GITHUB_STATS.commits,
  className,
}: GitHubStatsProps = {}) {
  return (
    <div className={cn('grid grid-cols-1 md:grid-cols-3 gap-4 w-full', className)}>
      <GitHubStatsCard type="stars" label="GitHub stars" value={stars} />
      <GitHubStatsCard type="forks" label="Forks" value={forks} />
      <GitHubStatsCard type="commits" label="Commits" value={commits} />
    </div>
  )
}

'use client'

import { motion } from 'motion/react'
import * as React from 'react'
import { Frame } from '@/components/ui/frame'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/spaceui/badge-squircle'
import { Tooltip, TooltipTrigger, TooltipContent } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import type { ContributionData } from './types'

export interface ContributionGraphCardProps {
  contributions: ContributionData
  className?: string
  delay?: number
}

function GithubSvg({ size = 24, className }: { size?: number | string; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.53 1.032 1.53 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z"
      />
    </svg>
  )
}

const CONTRIBUTION_LEVEL_COLORS = {
  NONE: 'bg-border',
  FIRST_QUARTILE: 'bg-green-200 dark:bg-green-900/60',
  SECOND_QUARTILE: 'bg-green-400 dark:bg-green-700',
  THIRD_QUARTILE: 'bg-green-500 dark:bg-green-500',
  FOURTH_QUARTILE: 'bg-green-600 dark:bg-green-400',
} as const

const levelColorsHover = {
  NONE: 'group-hover/cell:bg-border/80',
  FIRST_QUARTILE: 'group-hover/cell:bg-green-300',
  SECOND_QUARTILE: 'group-hover/cell:bg-green-500',
  THIRD_QUARTILE: 'group-hover/cell:bg-green-600',
  FOURTH_QUARTILE: 'group-hover/cell:bg-green-700',
}

function formatDate(dateString: string): string {
  const parts = dateString.split('-').map(Number)
  const year = parts[0]
  const month = parts[1]
  const day = parts[2]
  if (year === undefined || month === undefined || day === undefined) {
    return dateString
  }
  const date = new Date(year, month - 1, day)
  return date.toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })
}

export function ContributionGraphCard({ contributions, className, delay = 0 }: ContributionGraphCardProps) {
  const monthLabels = React.useMemo(() => {
    const months: { label: string; index: number }[] = []
    let currentMonth = -1

    contributions.weeks.forEach((week, weekIndex) => {
      const firstDay = week.contributionDays[0]
      if (firstDay) {
        const date = new Date(firstDay.date)
        const month = date.getMonth()
        if (month !== currentMonth) {
          currentMonth = month
          months.push({
            label: date.toLocaleDateString('en-US', { month: 'short' }),
            index: weekIndex,
          })
        }
      }
    })

    return months
  }, [contributions.weeks])

  return (
    <Frame
      className={cn(
        'h-full md:col-span-10 size-full max-w-[95%] bg-muted squircle-4xl/80 md:squircle-6xl/80 border-0 overflow-hidden mx-auto p-4 gap-2',
        className,
      )}
    >
      <Card className="relative flex flex-col justify-between size-full px-4 py-6 md:px-6 md:py-8 squircle-2xl/60 md:squircle-4xl/60 bg-background border-0 overflow-hidden before:hidden shadow-none">
        {/* Header */}
        <div className="relative z-20 mb-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Badge
              className="capitalize text-xs font-medium bg-[#8e8eff] text-white size-max squircle-2xl/80 md:squircle-3xl/80 text-primary-foreground!"
              size="sm"
              variant="default"
            >
              <GithubSvg size={32} />
            </Badge>
            <div>
              <h6 className="font-medium text-foreground">Contributions</h6>
              <p className="text-sm text-muted-foreground">This year</p>
            </div>
          </div>
          <div className="text-right">
            <span className="text-2xl font-semibold tracking-tight text-foreground">
              {contributions.totalContributions}
            </span>
            <p className="text-xs text-muted-foreground">contributions</p>
          </div>
        </div>

        {/* Graph */}
        <div className="relative z-20 mt-2 flex-1">
          {/* Mobile view with horizontal scroll */}
          <div className="overflow-x-auto md:hidden">
            <div className="w-fit">
              <div className="mb-1 flex text-[10px] text-muted-foreground" style={{ paddingLeft: '28px' }}>
                <div className="flex" style={{ gap: '2px' }}>
                  {contributions.weeks.map((week, weekIndex) => {
                    const showMonth = monthLabels.some((m) => m.index === weekIndex)
                    const monthLabel = showMonth ? monthLabels.find((m) => m.index === weekIndex)?.label : ''
                    return (
                      <div key={weekIndex} className="w-[10px] text-center">
                        {monthLabel && <span className="whitespace-nowrap">{monthLabel}</span>}
                      </div>
                    )
                  })}
                </div>
              </div>

              <div className="flex gap-[2px]">
                <div className="flex w-6 shrink-0 flex-col text-[9px] text-muted-foreground" style={{ gap: '2px' }}>
                  <div className="h-[10px]" />
                  <div className="flex h-[10px] items-center">Mon</div>
                  <div className="h-[10px]" />
                  <div className="flex h-[10px] items-center">Wed</div>
                  <div className="h-[10px]" />
                  <div className="flex h-[10px] items-center">Fri</div>
                  <div className="h-[10px]" />
                </div>
                <div className="flex" style={{ gap: '2px' }}>
                  {contributions.weeks.map((week, weekIndex) => (
                    <motion.div
                      key={weekIndex}
                      initial={{ opacity: 0, scale: 0.5 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{
                        duration: 0.3,
                        delay: delay + 0.3 + weekIndex * 0.005,
                        ease: 'easeOut',
                      }}
                      className="flex flex-col"
                      style={{ gap: '2px' }}
                    >
                      {week.contributionDays.map((day, dayIndex) => (
                        <Tooltip key={dayIndex}>
                          <TooltipTrigger>
                            <div className={cn('group/cell relative aspect-square')}>
                              <div
                                className={cn(
                                  'h-[10px] w-[10px] aspect-square rounded-sm transition-colors duration-150',
                                  CONTRIBUTION_LEVEL_COLORS[day.contributionLevel],
                                  levelColorsHover[day.contributionLevel],
                                )}
                              />
                            </div>
                          </TooltipTrigger>
                          <TooltipContent className="bg-popover text-popover-foreground text-xs p-2 rounded-md shadow-md border">
                            <div className="font-medium">
                              {day.contributionCount} contribution
                              {day.contributionCount !== 1 ? 's' : ''}
                            </div>
                            <div className="text-muted-foreground">{formatDate(day.date)}</div>
                          </TooltipContent>
                        </Tooltip>
                      ))}
                    </motion.div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Desktop view */}
          <div className="hidden md:block">
            <div className="mb-1 flex text-[10px] text-muted-foreground" style={{ paddingLeft: '28px' }}>
              <div className="flex flex-1 justify-between">
                {monthLabels.map((month, i) => (
                  <span key={i}>{month.label}</span>
                ))}
              </div>
            </div>

            <div className="flex gap-[3px]">
              <div className="flex w-6 shrink-0 flex-col justify-between py-[2px] text-[9px] text-muted-foreground">
                <span></span>
                <span>Mon</span>
                <span></span>
                <span>Wed</span>
                <span></span>
                <span>Fri</span>
                <span></span>
              </div>
              <div
                className="grid flex-1"
                style={{
                  gridTemplateColumns: `repeat(${contributions.weeks.length}, 1fr)`,
                  gap: '3px',
                }}
              >
                {contributions.weeks.map((week, weekIndex) => (
                  <motion.div
                    key={weekIndex}
                    initial={{ opacity: 0, scale: 0.5 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{
                      duration: 0.3,
                      delay: delay + 0.3 + weekIndex * 0.005,
                      ease: 'easeOut',
                    }}
                    className="flex flex-col gap-[3px]"
                  >
                    {week.contributionDays.map((day, dayIndex) => (
                      <Tooltip key={dayIndex}>
                        <TooltipTrigger>
                          <div className={cn('group/cell relative aspect-square')}>
                            <div
                              className={cn(
                                'h-full w-full aspect-square rounded-sm transition-colors duration-150 lg:rounded-md',
                                CONTRIBUTION_LEVEL_COLORS[day.contributionLevel],
                                levelColorsHover[day.contributionLevel],
                              )}
                            />
                          </div>
                        </TooltipTrigger>
                        <TooltipContent className="bg-popover text-popover-foreground text-xs p-2 rounded-md shadow-md border">
                          <div className="font-medium">
                            {day.contributionCount} contribution
                            {day.contributionCount !== 1 ? 's' : ''}
                          </div>
                          <div className="text-muted-foreground">{formatDate(day.date)}</div>
                        </TooltipContent>
                      </Tooltip>
                    ))}
                  </motion.div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Legend */}
        <div className="relative z-20 mt-3 flex items-center justify-center gap-1 text-[10px] text-muted-foreground md:justify-end">
          <span>Less</span>
          {(['NONE', 'FIRST_QUARTILE', 'SECOND_QUARTILE', 'THIRD_QUARTILE', 'FOURTH_QUARTILE'] as const).map(
            (level) => (
              <div key={level} className={`h-[10px] w-[10px] rounded-[2px] ${CONTRIBUTION_LEVEL_COLORS[level]}`} />
            ),
          )}
          <span>More</span>
        </div>
      </Card>
    </Frame>
  )
}
